import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import {
  SearchInput,
  Select,
  filterActiveCompaniesForUser,
  resolveUserCompanyScope,
} from '@linm-soft-org/linm-web-common-components';
import { companyService, type ActiveCompanyItem } from '../../services/companyService';
import { createAdminAccountSearchConfig } from '../../components/search/createAdminAccountSearchConfig';
import type { AdminAccountListItem } from '../../services/admin';
import {
  defaultCompanyAccountSearchFormData,
  type CompanyAccountSearchFormData,
} from '../../types/companyAccountSearch';
import { useAppSelector } from '../../store/hooks';
import { useAppToast } from '../../hooks/useAppToast';
import { buildAccountLookupCopyText } from '../../utils/accountLookupCopyText';
import { exportAccountLookupExcel } from '../../utils/exportAccountLookupExcel';
import { fetchAllCompanyAccounts } from '../../utils/fetchAllCompanyAccounts';
import { adminAccountsService } from '../../services/admin';
import { formatCompanyOptionLabel } from '../../utils/formatCompanyOptionLabel';
import { getAccountRoleLabel } from '../../utils/accountRoleLabels';
import { Pagination } from '../../components/common/Pagination/Pagination';
import styles from './CompanyAccountSearchPage.module.css';

const LIST_PAGE_SIZE = 20;

export interface CompanyAccountSearchFormProps {
  initialData?: CompanyAccountSearchFormData;
  onAccountSelect?: (account: AdminAccountListItem | null) => void;
}

export const CompanyAccountSearchForm: React.FC<CompanyAccountSearchFormProps> = ({
  initialData,
  onAccountSelect,
}) => {
  const [form, setForm] = useState<CompanyAccountSearchFormData>(
    initialData ?? defaultCompanyAccountSearchFormData,
  );
  const [companies, setCompanies] = useState<ActiveCompanyItem[]>([]);
  const [companiesLoading, setCompaniesLoading] = useState(true);
  const [copied, setCopied] = useState(false);
  const [showAllList, setShowAllList] = useState(false);
  const [listAccounts, setListAccounts] = useState<AdminAccountListItem[]>([]);
  const [listTotal, setListTotal] = useState(0);
  const [listPage, setListPage] = useState(1);
  const [loadingList, setLoadingList] = useState(false);
  const [exporting, setExporting] = useState(false);
  const [exportMenuOpen, setExportMenuOpen] = useState(false);
  const exportMenuRef = useRef<HTMLDivElement>(null);
  const user = useAppSelector((state) => state.auth.user);
  const toast = useAppToast();

  const scopedCompanies = useMemo(() => {
    if (!companies.length) return [];
    const scope = resolveUserCompanyScope(user);
    return filterActiveCompaniesForUser(
      companies,
      scope.canViewAllCompanies,
      scope.allowedCompanyCodes,
      scope.homeCompanyCode,
    );
  }, [companies, user]);

  const showCompanyPicker = scopedCompanies.length > 1;

  const resolvedCompanyCode =
    form.companyCode
    || (scopedCompanies.length === 1 ? scopedCompanies[0]?.id : undefined)
    || user?.companyCode
    || undefined;

  const resolvedCompanyLabel = useMemo(() => {
    if (!resolvedCompanyCode) return '';
    const match = scopedCompanies.find((c) => c.id === resolvedCompanyCode);
    return match ? formatCompanyOptionLabel(match) : '';
  }, [resolvedCompanyCode, scopedCompanies]);

  useEffect(() => {
    let cancelled = false;
    const timer = setTimeout(() => {
      companyService
        .getActiveList()
        .then((items) => {
          if (!cancelled) setCompanies(items);
        })
        .catch(() => {
          if (!cancelled) setCompanies([]);
        })
        .finally(() => {
          if (!cancelled) setCompaniesLoading(false);
        });
    }, 0);
    return () => {
      cancelled = true;
      clearTimeout(timer);
    };
  }, []);

  useEffect(() => {
    if (companiesLoading || scopedCompanies.length !== 1) return;
    const onlyId = scopedCompanies[0]?.id;
    if (!onlyId || form.companyCode === onlyId) return;

    const timer = setTimeout(() => {
      setForm({ ...defaultCompanyAccountSearchFormData, companyCode: onlyId });
      onAccountSelect?.(null);
    }, 0);
    return () => clearTimeout(timer);
  }, [companiesLoading, scopedCompanies, form.companyCode, onAccountSelect]);

  const companyOptions = useMemo(
    () => [
      { value: '', label: '— Chọn công ty —' },
      ...scopedCompanies.map((c) => ({
        value: c.id,
        label: formatCompanyOptionLabel(c),
      })),
    ],
    [scopedCompanies],
  );

  const accountSearchConfig = useMemo(
    () => createAdminAccountSearchConfig(resolvedCompanyCode),
    [resolvedCompanyCode],
  );

  const handleCompanyChange = (value: string) => {
    setForm({
      ...defaultCompanyAccountSearchFormData,
      companyCode: value,
    });
    setShowAllList(false);
    setListAccounts([]);
    setListTotal(0);
    setListPage(1);
    setExportMenuOpen(false);
    onAccountSelect?.(null);
  };

  const handleAccountChange = (item: AdminAccountListItem) => {
    setForm((prev) => ({
      ...prev,
      accountId: item.id,
      username: item.username,
      fullName: item.fullName,
      email: item.email,
      role: item.role,
    }));
    onAccountSelect?.(item);
  };

  const handleAccountClear = () => {
    setForm((prev) => ({
      ...prev,
      accountId: '',
      username: '',
      fullName: '',
      email: '',
      role: '',
    }));
    onAccountSelect?.(null);
  };

  const accountSearchDisabled = !resolvedCompanyCode || companiesLoading;

  const handleCopyAccount = useCallback(async () => {
    if (!form.username) return;
    const text = buildAccountLookupCopyText(form.fullName, form.username);
    try {
      await navigator.clipboard.writeText(text);
      setCopied(true);
      toast.success('Đã sao chép thông tin tài khoản');
      setTimeout(() => setCopied(false), 1500);
    } catch {
      toast.error('Không copy được — kiểm tra quyền clipboard trình duyệt');
    }
  }, [form.fullName, form.username, toast]);

  const listTotalPages = Math.max(1, Math.ceil(listTotal / LIST_PAGE_SIZE));

  const loadListPage = useCallback(async (page: number) => {
    if (!resolvedCompanyCode) return;
    setLoadingList(true);
    try {
      const res = await adminAccountsService.getAccounts({
        companyCode: resolvedCompanyCode,
        status: 'Active',
        page,
        pageSize: LIST_PAGE_SIZE,
      });
      setListAccounts(res.items);
      setListTotal(res.total ?? 0);
      setListPage(res.page ?? page);
    } catch {
      toast.error('Không thể tải danh sách tài khoản');
      setListAccounts([]);
      setListTotal(0);
    } finally {
      setLoadingList(false);
    }
  }, [resolvedCompanyCode, toast]);

  useEffect(() => {
    if (!showAllList || !resolvedCompanyCode) return;
    const timer = setTimeout(() => {
      void loadListPage(listPage);
    }, 0);
    return () => clearTimeout(timer);
  }, [showAllList, resolvedCompanyCode, listPage, loadListPage]);

  useEffect(() => {
    if (!exportMenuOpen) return;
    const close = (event: MouseEvent) => {
      if (exportMenuRef.current && !exportMenuRef.current.contains(event.target as Node)) {
        setExportMenuOpen(false);
      }
    };
    document.addEventListener('mousedown', close);
    return () => document.removeEventListener('mousedown', close);
  }, [exportMenuOpen]);

  const handleToggleShowAll = useCallback(() => {
    if (!resolvedCompanyCode) return;
    if (showAllList) {
      setShowAllList(false);
      setExportMenuOpen(false);
      return;
    }
    setListPage(1);
    setShowAllList(true);
  }, [resolvedCompanyCode, showAllList]);

  const handleListPageChange = useCallback((page: number) => {
    setListPage(page);
  }, []);

  const handleExportExcel = useCallback(async (scope: 'page' | 'all') => {
    if (!resolvedCompanyCode) return;
    setExportMenuOpen(false);
    setExporting(true);
    try {
      let items: AdminAccountListItem[] = [];
      if (scope === 'page') {
        if (listAccounts.length > 0 && showAllList) {
          items = listAccounts;
        } else {
          const res = await adminAccountsService.getAccounts({
            companyCode: resolvedCompanyCode,
            status: 'Active',
            page: showAllList ? listPage : 1,
            pageSize: LIST_PAGE_SIZE,
          });
          items = res.items;
        }
        if (!items.length) {
          toast.error('Không có tài khoản trên trang hiện tại để xuất');
          return;
        }
        exportAccountLookupExcel(items, resolvedCompanyLabel, 'page', showAllList ? listPage : 1);
      } else {
        items = await fetchAllCompanyAccounts(resolvedCompanyCode);
        if (!items.length) {
          toast.error('Không có tài khoản để xuất');
          return;
        }
        exportAccountLookupExcel(items, resolvedCompanyLabel, 'all');
      }
      toast.success('Xuất Excel thành công');
    } catch {
      toast.error('Xuất Excel thất bại');
    } finally {
      setExporting(false);
    }
  }, [
    listAccounts,
    listPage,
    resolvedCompanyCode,
    resolvedCompanyLabel,
    showAllList,
    toast,
  ]);

  return (
    <div className={styles.form} data-testid="home-account-search-form">
      {showCompanyPicker && (
        <div className={styles.section}>
          <h2 className={styles.sectionTitle}>Chọn công ty</h2>
          <div className={styles.row2}>
            <Select
              label="Công ty"
              value={form.companyCode}
              onChange={(e) => handleCompanyChange(e.target.value)}
              options={companyOptions}
              fullWidth
              disabled={companiesLoading}
              data-testid="home-account-search-field-company"
            />
          </div>
          {!form.companyCode && !companiesLoading && (
            <p className={styles.hint}>
              Chọn đơn vị cơ sở để lọc tài khoản thuộc công ty đó.
            </p>
          )}
        </div>
      )}

      <div className={styles.section}>
        <div className={styles.sectionHeader}>
          <h2 className={styles.sectionTitle}>Tìm tài khoản</h2>
          <div className={styles.sectionActions}>
            <button
              type="button"
              className={styles.actionBtn}
              onClick={() => void handleToggleShowAll()}
              disabled={accountSearchDisabled || loadingList}
              data-testid="home-account-search-show-all-btn"
            >
              <i className={`fas ${showAllList ? 'fa-eye-slash' : 'fa-list'}`} />
              {showAllList ? 'Ẩn danh sách' : 'Hiện tất cả'}
            </button>
            <div className={styles.exportMenu} ref={exportMenuRef}>
              <button
                type="button"
                className={styles.actionBtn}
                onClick={() => setExportMenuOpen((open) => !open)}
                disabled={accountSearchDisabled || exporting}
                data-testid="home-account-search-export-btn"
              >
                <i className="fas fa-file-excel" />
                {exporting ? 'Đang xuất...' : 'Xuất Excel'}
                <i className={`fas fa-chevron-${exportMenuOpen ? 'up' : 'down'}`} />
              </button>
              {exportMenuOpen && (
                <div className={styles.exportDropdown} data-testid="home-account-search-export-menu">
                  <button
                    type="button"
                    className={styles.exportMenuItem}
                    disabled={exporting}
                    onClick={() => void handleExportExcel('page')}
                    data-testid="home-account-search-export-page-btn"
                  >
                    Trang hiện tại
                  </button>
                  <button
                    type="button"
                    className={styles.exportMenuItem}
                    disabled={exporting}
                    onClick={() => void handleExportExcel('all')}
                    data-testid="home-account-search-export-all-btn"
                  >
                    Tất cả
                  </button>
                </div>
              )}
            </div>
          </div>
        </div>
        <div className={styles.formCell}>
          <label className={styles.fieldLabel}>Tài khoản người dùng</label>
          <SearchInput
            config={accountSearchConfig}
            value={form.accountId}
            primaryDisplay={form.username}
            secondaryDisplay={form.fullName}
            showLabel={false}
            placeholder="Tìm theo username, họ tên, email..."
            showSecondaryInput
            disabled={accountSearchDisabled}
            className={styles.accountSearchField}
            onChange={handleAccountChange}
            onClear={handleAccountClear}
            data-testid="home-account-search-field-account"
          />
        </div>
      </div>

      {showAllList && (
        <div className={styles.section} data-testid="home-account-search-all-list">
          <div className={styles.allListHeader}>
            <h2 className={styles.sectionTitle}>Danh sách tài khoản</h2>
            <span className={styles.allListCount}>
              {loadingList ? 'Đang tải...' : `${listTotal} tài khoản`}
            </span>
          </div>
          {loadingList ? (
            <p className={styles.hint}>Đang tải danh sách...</p>
          ) : listAccounts.length === 0 ? (
            <p className={styles.hint}>Không có tài khoản active trong công ty này.</p>
          ) : (
            <>
              <div className={styles.allListScroll}>
                <table className={styles.allListTable}>
                  <thead>
                    <tr>
                      <th>Tài khoản</th>
                      <th>Username</th>
                    </tr>
                  </thead>
                  <tbody>
                    {listAccounts.map((item) => (
                      <tr key={item.id}>
                        <td>{item.fullName.trim() || item.username}</td>
                        <td>{item.username}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
              {listTotal > 0 && (
                <div className={styles.listPagination}>
                  <Pagination
                    currentPage={listPage}
                    totalPages={listTotalPages}
                    totalCount={listTotal}
                    pageSize={LIST_PAGE_SIZE}
                    itemLabel="tài khoản"
                    onPageChange={handleListPageChange}
                  />
                </div>
              )}
            </>
          )}
        </div>
      )}

      {form.accountId && (
        <div className={styles.section} data-testid="home-account-search-preview">
          <div className={styles.previewHeader}>
            <h2 className={styles.sectionTitle}>Tài khoản đã chọn</h2>
            <button
              type="button"
              className={`${styles.copyBtn} ${copied ? styles.copyBtnCopied : ''}`}
              onClick={() => void handleCopyAccount()}
              data-testid="home-account-search-copy-btn"
            >
              <i className={`fas ${copied ? 'fa-check' : 'fa-copy'}`} />
              {copied ? 'Đã copy' : 'Copy'}
            </button>
          </div>
          <dl className={styles.previewGrid}>
            <div>
              <dt>Tài khoản</dt>
              <dd>{form.username || '—'}</dd>
            </div>
            <div>
              <dt>Họ và tên</dt>
              <dd>{form.fullName || '—'}</dd>
            </div>
            <div>
              <dt>Email</dt>
              <dd>{form.email || '—'}</dd>
            </div>
            <div>
              <dt>Vai trò</dt>
              <dd>{getAccountRoleLabel(form.role)}</dd>
            </div>
          </dl>
        </div>
      )}
    </div>
  );
};
